import re

_COMPONENT = re.compile(r"([0-9]+)(?:\.([0-9]+))?(ms|[wdhms])")
_MILLISECONDS = {"w": 604800000, "d": 86400000, "h": 3600000,
                 "m": 60000, "s": 1000, "ms": 1}


def _integer(digits):
    # Convert in chunks so valid inputs can exceed Python's int-string limit.
    value = 0
    for start in range(0, len(digits), 500):
        chunk = digits[start:start + 500]
        value = value * 10 ** len(chunk) + int(chunk)
    return value


def parse_duration(text):
    """Return the signed duration rounded to the nearest millisecond."""
    if not isinstance(text, str):
        raise TypeError("duration must be a string")
    text = text.strip()
    negative = text.startswith("-")
    position = int(negative)
    total = 0
    previous = None
    while True:
        match = _COMPONENT.match(text, position)
        if match is None:
            raise ValueError("expected a duration component")
        whole, fraction, unit = match.groups()
        scale = _MILLISECONDS[unit]
        if previous is not None and scale >= previous:
            raise ValueError("units must be strictly descending")
        previous = scale
        total += _integer(whole) * scale
        position = match.end()
        if fraction is not None:
            if position != len(text):
                raise ValueError("only the final component may have a fraction")
            denominator = 10 ** len(fraction)
            total += (_integer(fraction) * scale + denominator // 2) // denominator
        if position == len(text):
            return -total if negative else total
        if text[position] == " ":
            position += 1
